## The lcn-gen outputs committed under tests/generated/ (and the common types
## and mirrors under src/), regenerated by `nimble regen` and compared by
## tests/test_nimgen.nim. The C headers are there for the kit's C harness
## (tests/kit/typed_harness.c), which the kit tests compile.

import std/[os, sequtils]
import results
import ../../src/logos_core/iface/[accept, cmap]
import ../../src/logos_core/codegen/[callsgen, cmirror, hostgen, kitgen, nimgen]

type NimFixture* = object
  module*: string ## the file under tests/generated/
  primary*: string
  interfaces*, supporting*: seq[string]
  system*: bool
  kit*: bool ## the module kit (`kitgen`) rather than the types
  calls*: bool ## the typed call helpers (`callsgen`) rather than the types

const
  fixturePrefix* = "../../src/logos_core/"
  nimFixtures* = [
    NimFixture(
      module: "meter_module_types.nim", primary: "spec/mirrors/IFC/3.9.1.module.cddl"
    ),
    NimFixture(
      module: "sensor_module_types.nim",
      primary: "spec/mirrors/IFC/3.9.2.module.cddl",
      interfaces: @["spec/mirrors/IFC/3.9.2.interface.cddl"],
      supporting: @["spec/mirrors/IFC/3.9.2.supporting.cddl"],
    ),
    NimFixture(
      module: "recursive_types.nim", primary: "spec/mirrors/IFC/3.9.3.module.cddl"
    ),
    NimFixture(module: "demo_types.nim", primary: "tests/generated/demo.cddl"),
    NimFixture(
      module: "meter_module_kit.nim",
      primary: "spec/mirrors/IFC/3.9.1.module.cddl",
      kit: true,
    ),
    NimFixture(
      module: "sensor_module_kit.nim",
      primary: "spec/mirrors/IFC/3.9.2.module.cddl",
      interfaces: @["spec/mirrors/IFC/3.9.2.interface.cddl"],
      supporting: @["spec/mirrors/IFC/3.9.2.supporting.cddl"],
      kit: true,
    ),
    NimFixture(
      module: "shapes_module_types.nim", primary: "tests/kit/shapes_module.cddl"
    ),
    NimFixture(
      module: "shapes_module_kit.nim",
      primary: "tests/kit/shapes_module.cddl",
