      module: "metrics_provider_types.nim",
      primary: "spec/mirrors/IFC/3.9.2.interface.cddl",
    ),
    NimFixture(
      module: "metrics_provider_calls.nim",
      primary: "spec/mirrors/IFC/3.9.2.interface.cddl",
      calls: true,
    ),
  ]

proc generated*(f: NimFixture): Result[string, string] =
  ## The module lcn-gen makes for `f` now.
  try:
    let set = ?acceptContractSet(
      readFile(f.primary),
      f.interfaces.mapIt(readFile(it)),
      f.supporting.mapIt(readFile(it)),
      AcceptOptions(system: f.system),
    )
    if f.kit:
      kitModule(set, KitOptions(importPrefix: fixturePrefix), f.system)
    elif f.calls:
      callsModule(set, CallsOptions(importPrefix: fixturePrefix), f.system)
    else:
      nimModule(set, NimOptions(importPrefix: fixturePrefix), f.system)
  except IOError as e:
    err(e.msg)

type HeaderFixture* = object
  header*: string ## the file under tests/generated/
  primary*: string ## none: `logos_types.h`
  interfaces*, supporting*: seq[string]
  calls*: bool ## the call helpers' header (`callsHeader`)
  runtime*: bool ## `logos_runtime.h` (RUNTIME §13)

const headerFixtures* = [
  HeaderFixture(header: "logos_types.h"),
  HeaderFixture(header: "logos_runtime.h", runtime: true),
  HeaderFixture(
    header: "meter_module_types.h", primary: "spec/mirrors/IFC/3.9.1.module.cddl"
  ),
  HeaderFixture(
    header: "sensor_module_types.h",
    primary: "spec/mirrors/IFC/3.9.2.module.cddl",
    interfaces: @["spec/mirrors/IFC/3.9.2.interface.cddl"],
    supporting: @["spec/mirrors/IFC/3.9.2.supporting.cddl"],
  ),
  HeaderFixture(
    header: "shapes_module_types.h", primary: "tests/kit/shapes_module.cddl"
  ),
  HeaderFixture(
    header: "metrics_provider_types.h", primary: "spec/mirrors/IFC/3.9.2.interface.cddl"
  ),
  HeaderFixture(
    header: "meter_module_calls.h",
    primary: "spec/mirrors/IFC/3.9.1.module.cddl",
    calls: true,
  ),
  HeaderFixture(
    header: "sensor_module_calls.h",
    primary: "spec/mirrors/IFC/3.9.2.module.cddl",
    interfaces: @["spec/mirrors/IFC/3.9.2.interface.cddl"],
    supporting: @["spec/mirrors/IFC/3.9.2.supporting.cddl"],
    calls: true,
  ),
  HeaderFixture(
    header: "shapes_module_calls.h",
    primary: "tests/kit/shapes_module.cddl",
    calls: true,
  ),
  HeaderFixture(
    header: "metrics_provider_calls.h",
    primary: "spec/mirrors/IFC/3.9.2.interface.cddl",
    calls: true,
  ),
]

proc generated*(f: HeaderFixture): Result[string, string] =
  ## The header lcn-gen makes for `f` now.
  if f.runtime:
    return ok(logosRuntimeHeader())
  if f.primary.len == 0:
    return ok(logosTypesHeader())
  try:
    let set = ?acceptContractSet(
      readFile(f.primary),
      f.interfaces.mapIt(readFile(it)),
      f.supporting.mapIt(readFile(it)),
      AcceptOptions(),
    )
    if f.calls:
      callsHeader(set.cSchemaSet)
    else:
      contractHeader(set.cSchemaSet)
  except IOError as e:
    err(e.msg)

proc fixturePath*(f: HeaderFixture): string =
  "tests/generated" / f.header

proc generatedCommon*(): Result[string, string] =
  commonNimModule(NimOptions(importPrefix: "../"))

proc generatedCommonMirrors*(): Result[string, string] =
  commonMirrorModule("../")

const
  commonTypesPath* = "src/logos_core/iface/common_types.nim"
  commonMirrorsPath* = "src/logos_core/codegen/common_mirrors.nim"
  rcTypesPath* = "src/logos_core/runtime/rc_types.nim"
  rcPrimary* = "spec/mirrors/RNT/9.3.runtime-control.cddl"
  rcSupporting* = [
    "spec/mirrors/RNT/9.2.runtime-types.cddl",
    "spec/mirrors/CFG/9.configuration-types.cddl",
  ]

proc generatedRcTypes*(): Result[string, string] =
  ## The Runtime Control contract's types (RUNTIME §9.2, §9.3; CONFIG §9), for
  ## the engine.
  try:
    let set = ?acceptContractSet(
      readFile(rcPrimary),
      [],
      rcSupporting.mapIt(readFile(it)),
      AcceptOptions(system: true),
    )
    nimModule(set, NimOptions(importPrefix: "../", schemaAccessor: "rcSchema"), true)
  except IOError as e:
    err(e.msg)

const
  hostConfigTypesPath* = "src/logos_core/runtime/host_config_types.nim"
  hostConfigPrimary* = "src/logos_core/runtime/host_config.cddl"

proc generatedHostConfigTypes*(): Result[string, string] =
  ## The host configuration format's types (`logos-core-nim.app-config.v1`,
  ## G76), for the host layer.
  try:
    let set = ?acceptContractSet(readFile(hostConfigPrimary), [], [], AcceptOptions())
    nimModule(
      set, NimOptions(importPrefix: "../", schemaAccessor: "hostConfigSchema"), false
    )
  except IOError as e:
    err(e.msg)

proc fixturePath*(f: NimFixture): string =
  "tests/generated" / f.module
